use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 3);
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

/// Parse a JSON array of strings, e.g. `["a", "b"]`. Returns None if malformed.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => break,
            '"' => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            '"' => cur.push('"'),
                            '\\' => cur.push('\\'),
                            '/' => cur.push('/'),
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            'b' => cur.push('\u{8}'),
                            'f' => cur.push('\u{c}'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                cur.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                            }
                            _ => return None,
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
                while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
                    chars.next();
                }
                match chars.next()? {
                    ',' => continue,
                    ']' => break,
                    _ => return None,
                }
            }
            _ => return None,
        }
    }
    Some(out)
}

fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        parse_json_string_array(trimmed).unwrap_or_default()
    } else {
        trimmed.lines().map(|l| l.to_string()).collect()
    };
    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() || u.starts_with('#') {
            continue;
        }
        if !urls.iter().any(|x| x == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment request (approved http-client grant). The result is
        // deliberately not used, so the node's output is unchanged; a transport
        // failure is returned as a value and ignored.
        let enrich_url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
        let _ = http_client::fetch(&enrich_url);

        let mut urls = Vec::new();
        for key in ["subscriptions", "urls"] {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        // ensures present(urls): refuse rather than emit an output that
        // violates the contract.
        if urls.is_empty() {
            panic!("LoadSubscriptions: no subscriptions found in state store");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
